    }

    /// <summary>瀹炰緥鍖栧崟涓埧闂?/summary>
    private void InstantiateRoom(RoomNode node)
    {
        var prefab = node.config.GetRandomPrefab();
        if (prefab == null)
        {
            Debug.LogError($"MapManager: RoomConfig '{node.config.name}' 娌℃湁棰勫埗浣?");
            return;
